export type BlueprintProcessState = 'intake'|'extracting'|'proposal_review'|'conflict_review'|'evaluating'|'discovering'|'document_ready'|'requirements_generating'|'requirements_draft'|'requirements_ready'|'prd_generating'|'prd_draft';
export type AiTaskType = 'QUESTION_COMPOSE'|'QUESTION_EXPLAIN'|'TURN_ANALYZE'|'OPTION_RECOMMEND'|'CONTEXT_COMPACT'|'REQUIREMENTS_DRAFT'|'REQUIREMENTS_REVIEW'|'REQUIREMENTS_REPAIR'|'PRD_DRAFT'|'PRD_REVIEW'|'PRD_REPAIR'|'DOCUMENT_PATCH'|'CONSISTENCY_REVIEW';
export type ModelProfile = 'LIGHT'|'DEFAULT'|'FINAL';
export type DocumentType = 'requirements'|'prd'|'setup_guide';
export interface BlueprintProject { id:string; ownerKey:string; schemaVersion:number; title:string; status:'active'|'ready'|'completed'|'archived'; activeDocumentType:DocumentType|'design'; activeThreadId:string; processState:BlueprintProcessState; readiness:ReadinessSummary; designRevision?:number; createdAt:string; updatedAt:string; lastOpenedAt:string; aiConsent?:{acceptedAt:string;consentVersion:string} }
export interface ConversationThread { id:string; projectId:string; title:string; status:'active'|'closed'; summary?:ConversationSummary; createdAt:string; updatedAt:string }
export interface ConversationSummary { confirmedFacts:SummaryFact[]; explicitUnknowns:SummaryFact[]; rejectedDirections:SummaryFact[]; unresolvedQuestions:SummaryFact[]; sourceMessageIds:string[] }
export interface SummaryFact { text:string; sourceMessageIds:string[] }
export interface ConversationMessage { id:string; threadId:string; logicalRequestId?:string; attemptId?:string; role:'user'|'assistant'|'system'; kind:'text'|'question'|'job_status'|'error'; content:string; question?:QuestionSpec; blocks?:DisplayBlock[]; sourceIds?:string[]; createdAt:string }
export interface QuestionSpec { id:string; topic:string; prompt:string; help?:string; answerMode:'single'|'multiple'|'text'|'number'|'range'|'rank'|'confirm'; required:boolean; allowCustomAnswer:boolean; allowUnknown:boolean; allowDefer:boolean; targetItemTypes:DesignItemType[]; options?:QuestionOption[] }
export interface QuestionOption { value:string; label:string; description?:string; recommended?:boolean; recommendationReason?:string }
export interface QuestionAnswer { id:string; projectId:string; threadId:string; questionId:string; logicalRequestId:string; answerMode:QuestionSpec['answerMode']; action:'answer'|'unknown'|'recommend'|'defer'|'skip'; selectedValues?:string[]; customText?:string; numberValue?:number; rangeValue?:{start:number;end:number}; rankedValues?:string[]; createdAt:string }
export interface SourceDocument { id:string; projectId:string; fileName:string; mediaType:string; size:number; extractionStatus:'queued'|'extracting'|'ready'|'unsupported'|'failed'; extractedText?:string; textHash?:string; preview?:string; errorCode?:string; createdAt:string; archivedAt?:string }
export type DesignItemType='product_definition'|'problem'|'goal'|'user_role'|'scenario'|'scope'|'out_of_scope'|'requirement'|'constraint'|'technical_decision'|'success_metric'|'risk'|'open_issue';
export interface DesignItem { id:string; projectId:string; parentId?:string; type:DesignItemType; key?:string; title:string; description:string; status:'proposed'|'confirmed'|'deferred'|'not_applicable'|'review_required'|'rejected'; priority?:'must'|'should'|'could'|'wont'; confidence?:number; attributes:Record<string,unknown>; evidence:EvidenceRef[]; acceptanceCriteria:AcceptanceCriterion[]; relatedItemIds:string[]; createdAt:string; updatedAt:string; confirmedAt?:string; archivedAt?:string }
export interface EvidenceRef { id:string; sourceType:'message'|'file'|'user_edit'|'agent_inference'; sourceId:string; excerpt?:string; location?:string; createdAt:string }
export interface AcceptanceCriterion { id:string; text:string; status:'draft'|'confirmed'|'review_required'; evidence:EvidenceRef[]; createdAt:string; updatedAt:string }
export interface ChangeProposal { id:string; projectId:string; logicalRequestId:string; operation:'create'|'update'|'delete'; targetType:'design_item'|'acceptance_criterion'|'document_section'; targetId?:string; before?:unknown; after?:unknown; rationale:string; evidence:EvidenceRef[]; affectedItemIds:string[]; status:'pending'|'accepted'|'edited_and_accepted'|'rejected'|'superseded'; createdAt:string; resolvedAt?:string }
export interface GeneratedDocument { id:string; projectId:string; type:DocumentType; title:string; status:'draft'|'review_required'|'ready'; designRevision:number; version:number; sectionIds:string[]; createdAt:string; updatedAt:string }
export interface DocumentSection { id:string; documentId:string; key:string; title:string; markdown:string; order:number; sourceItemIds:string[]; origin:'generated'|'user_edited'|'accepted_proposal'; syncStatus:'current'|'stale'|'conflict'; updatedAt:string }
export interface GenerationJob { id:string; projectId:string; logicalRequestId:string; attemptId:string; type:AiTaskType; promptVersion:string; schemaVersion:string; modelProfile:ModelProfile; resolvedModel:string; reasoningEffort:string; designRevision:number; status:'queued'|'running'|'succeeded'|'failed'|'cancelled'; targetIds:string[]; progress?:{step:string;completed:number;total:number}; errorCode?:string; startedAt?:string; finishedAt?:string }
export interface AiRequestLedgerEntry { id:string; projectId:string; generationJobId:string; logicalRequestId:string; attemptId:string; task:AiTaskType; promptVersion:string; schemaVersion:string; modelProfile:ModelProfile; resolvedModel:string; reasoningEffort:string; designRevision:number; estimatedInputTokens:number; estimatedCachedInputTokens?:number; estimatedOutputTokens:number; estimatedCostUsd:number; usage?:{inputTokens:number;cachedInputTokens?:number;outputTokens:number;reasoningTokens?:number;totalTokens:number}; actualCostUsd?:number; latencyMs?:number; status:'started'|'succeeded'|'failed'|'cancelled'|'unknown'; errorCode?:string; createdAt:string; finishedAt?:string }
export interface ContextManifest { projectId:string; designRevision:number; currentQuestionId?:string; designItemIds:string[]; sourceExcerptIds:string[]; recentMessageIds:string[]; summaryIds:string[]; omitted:{type:string;count:number;reason:string}[] }
export interface ReadinessSummary { state:'insufficient'|'workable'|'ready'; areas:{key:string;status:'missing'|'deferred'|'not_applicable'|'confirmed'|'review_required';itemIds:string[]}[]; pendingProposalCount:number; conflictCount:number }
export interface ActivityEntry { id:string; projectId:string; action:string; targetType:string; targetId?:string; logicalRequestId?:string; summary:string; createdAt:string }
export interface BlueprintAggregate { project:BlueprintProject; thread:ConversationThread; messages:ConversationMessage[]; answers:QuestionAnswer[]; sources:SourceDocument[]; designItems:DesignItem[]; proposals:ChangeProposal[]; documents:GeneratedDocument[]; sections:DocumentSection[]; generationJobs:GenerationJob[]; requestLedgerEntries:AiRequestLedgerEntry[]; contextManifests:ContextManifest[]; activityEntries:ActivityEntry[] }
export interface ProjectSummary { id:BlueprintProject['id']; title:BlueprintProject['title']; updatedAt:BlueprintProject['updatedAt']; lastOpenedAt:BlueprintProject['lastOpenedAt']; readiness:BlueprintProject['readiness']; activeDocumentType:BlueprintProject['activeDocumentType'] }
export type NextAction='continue_questions'|'generate_requirements'|'review_requirements'|'mark_requirements_ready'|'generate_prd'|'review_prd'|'download_document';
export type DisplayBlock={type:'assistant_text';content:string}|(QuestionSpec&{type:'question'})|{type:'explanation';title:string;summary:string;comparisons:{label:string;description:string;bestWhen?:string}[];example?:string;returnToQuestionId:string}|{type:'recommendation';questionId:string;recommendedValue:string;rationale:string;tradeoffs:string[];assumptions:string[]}|{type:'proposal_summary'|'conflict_notice';proposalIds:string[]}|{type:'readiness_notice';readiness:ReadinessSummary}|{type:'next_action';action:NextAction};
export interface AiWarning { code:string; severity:'info'|'warning'; message:string }
export interface AiResponseEnvelope<TPayload> { task:AiTaskType; promptVersion:string; schemaVersion:string; designRevision:number; payload:TPayload; referencedItemIds:string[]; referencedSourceIds:string[]; warnings:AiWarning[] }
export interface PromptDefinition<TInput,TOutput> { task:AiTaskType; promptId:string; promptVersion:string; schemaId:string; schemaVersion:string; modelProfile:ModelProfile; buildInput(input:TInput):unknown[]; validateDomain(output:TOutput,context:unknown):{valid:boolean;errors:string[]} }
export type PromptDefinitionMetadata = Pick<PromptDefinition<unknown,unknown>, 'task'|'promptId'|'promptVersion'|'schemaId'|'schemaVersion'|'modelProfile'>;
